355	func TestVerifyRacingAppendsNeverReportsFalseBreak(t *testing.T) {
356		const appenders = 8
357		const verifiers = 8
358		router := NewRouter(openTestStore(t))
359	
360		var wg sync.WaitGroup
361		results := make([]verifyBody, 0, verifiers*2)
362		var mu sync.Mutex
363		start := make(chan struct{})
364	
365		// Appenders commit continuously throughout the verification passes.
366		for i := 0; i < appenders; i++ {
367			wg.Add(1)
368			go func() {
369				defer wg.Done()
370				<-start
371				postEventBody(t, router, validEventBody())
372			}()
373		}
374		// Each verifier may run before, during or after the appends; every pass
375		// must see one complete committed chain.
376		for i := 0; i < verifiers; i++ {
377			wg.Add(1)
378			go func() {
379				defer wg.Done()
380				<-start
381				recorder := getLedgerVerifyRequest(t, router, "/ledger/verify")
382				if recorder.Code != http.StatusOK {
383					t.Errorf("verify status = %d (%s)", recorder.Code, recorder.Body.String())
384					return
385				}
386				body := decodeVerify(t, recorder)
387				mu.Lock()
388				results = append(results, body)
389				mu.Unlock()
390			}()
391		}
392		close(start)
393		wg.Wait()
394	
395		if len(results) != verifiers {
396			t.Fatalf("got %d verify results, want %d", len(results), verifiers)
397		}
398		for i, body := range results {
399			if !body.Valid || body.FirstInvalidSeq != nil {
400				t.Fatalf("verifier %d saw a mixed/invalid snapshot: %+v", i, body)
401			}
402			if body.Checked < 0 || body.Checked > appenders {
403				t.Fatalf("verifier %d checked = %d, outside 0..%d", i, body.Checked, appenders)
404			}
405		}
406	
407		// After everything settles the full chain verifies with all records.
408		recorder := getLedgerVerifyRequest(t, router, "/ledger/verify")
409		body := decodeVerify(t, recorder)
410		if !body.Valid || body.Checked != appenders || body.FirstInvalidSeq != nil {
411			t.Fatalf("final body = %+v, want valid/%d/null", body, appenders)
412		}
413	}
414	
415	func TestVerifyDoesNotInterfereWithAppendChaining(t *testing.T) {
416		router := NewRouter(openTestStore(t))
417		first := decodeEvent(t, postEventBody(t, router, validEventBody()))
418	
419		// A verification pass between appends changes neither seq assignment nor
420		// the back-link of the following record.
421		if recorder := getLedgerVerifyRequest(t, router, "/ledger/verify"); recorder.Code != http.StatusOK {
422			t.Fatalf("verify: %s", recorder.Body.String())
423		}
424		second := decodeEvent(t, postEventBody(t, router, validEventBody()))
425		if second["seq"] != float64(2) || second["prev_hash"] != first["hash"] {
426			t.Fatalf("second = %v, want seq 2 chained to %s", second, first["hash"])
427		}
428		if recorder := getLedgerVerifyRequest(t, router, "/ledger/verify"); recorder.Code != http.StatusOK {
429			t.Fatalf("verify: %s", recorder.Body.String())
430		}
431		third := decodeEvent(t, postEventBody(t, router, validEventBody()))
432		if third["seq"] != float64(3) || third["prev_hash"] != second["hash"] {
433			t.Fatalf("third = %v, want seq 3 chained to the seq 2 hash", third)
434		}
435	}
436	
437	func TestVerifyUnknownPathStill404(t *testing.T) {
438		router := NewRouter(openTestStore(t))
439		recorder := getLedgerVerifyRequest(t, router, "/ledger")
440		if recorder.Code != http.StatusNotFound {
441			t.Fatalf("/ledger status = %d, want 404", recorder.Code)
442		}
443		recorder = getLedgerVerifyRequest(t, router, fmt.Sprintf("/ledger/verify/extra"))
444		if recorder.Code != http.StatusNotFound {
445			t.Fatalf("/ledger/verify/extra status = %d, want 404", recorder.Code)
446		}
447	}
